import re

# Parse all flight data from the full hybrid_output2
# Extract the flight section
flight_section_match = re.search(r'SECTION 4: FLIGHT AVAILABILITY & PRICING\n={60}\n(.*?)(?:\n={60}|$)', hybrid_output2, re.DOTALL)
flight_lines = flight_section_match.group(1).strip() if flight_section_match else ""

# Parse individual flights
flights = []
current_flight = None
for line in flight_lines.split('\n'):
    line = line.strip()
    if not line:
        continue
    # Flight header: FL...: ORIG->DEST dep=HH:MM arr=HH:MM
    m = re.match(r'(FL\w+): (\w+)->(\w+) dep=(\S+) arr=(\S+)', line)
    if m:
        current_flight = {
            'id': m.group(1), 'origin': m.group(2), 'dest': m.group(3),
            'dep': m.group(4), 'arr': m.group(5), 'dates': []
        }
        flights.append(current_flight)
        continue
    # Date line: 2026-09-10: status=available, prices={...}, seats={...}
    m2 = re.match(r'(\d{4}-\d{2}-\d{2}): status=(\w+), prices=(\{[^}]+\}), seats=(\{[^}]+\})', line)
    if m2 and current_flight:
        current_flight['dates'].append({
            'date': m2.group(1), 'status': m2.group(2),
            'prices': m2.group(3), 'seats': m2.group(4)
        })

# Deduplicate flights by id (some appear twice for different dates)
seen = {}
unique_flights = []
for f in flights:
    if f['id'] not in seen:
        seen[f['id']] = f
        unique_flights.append(f)
    else:
        # Merge dates
        existing_dates = {d['date'] for d in seen[f['id']]['dates']}
        for d in f['dates']:
            if d['date'] not in existing_dates:
                seen[f['id']]['dates'].append(d)

print(f"Parsed {len(unique_flights)} unique flights")
for f in unique_flights:
    print(f"  {f['id']}: {f['origin']}->{f['dest']} {f['dep']}-{f['arr']} ({len(f['dates'])} dates)")
